27	const PROCESSING_FEE = 5;
28	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
29	
30	const percentOf = (amount: number, percent: number): number =>
31	  (amount * percent) / 100;
32	
33	const BASE_PREMIUMS: Record<string, number> = {
34	  sword: 100,
35	  amulet: 60,
36	};
37	
38	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
39	
40	const policyBasePremiumOf = (items: Item[]): number =>
41	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
42	
43	const quote = (step: QuoteStep): QuoteResult => {
44	  const basePremium = policyBasePremiumOf(step.items);
45	  const firstInsuranceSurcharge = percentOf(
46	    basePremium,
47	    FIRST_INSURANCE_SURCHARGE_PERCENT,
48	  );
49	
50	  return {
51	    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
52	  };
53	};
54	
55	export const runScenario = (scenario: Scenario): ScenarioResult => {
56	  return { results: scenario.steps.map(quote) };
57	};
