const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
} as const satisfies Record<string, number>;

type InsurableItemType = keyof typeof BASE_PREMIUMS;

const isInsurable = (type: string): type is InsurableItemType =>
  type in BASE_PREMIUMS;

const basePremiumOf = (item: Item): number =>
  isInsurable(item.type) ? BASE_PREMIUMS[item.type] : UNKNOWN_ITEM_BASE_PREMIUM;

const PROCESSING_FEE = 5;
// No test yet drives unknown item types; the spec ultimately requires an error.
const UNKNOWN_ITEM_BASE_PREMIUM = 0;
